/**
 * Arithmetic shared by every value on the sheet. Every divide on the sheet goes through
 * {@link #divide}, which rounds to the nearest whole number, a half rounding up to the larger
 * number (5 / 2 is 3, -5 / 2 is -2, -8 / 3 is -3).
 */
final class SheetMath {

    private SheetMath() {
    }

    static long divide(long dividend, long divisor) {
        if (divisor < 0) {
            dividend = -dividend;
            divisor = -divisor;
        }
        // floor(dividend / divisor + 1/2)
        return Math.floorDiv(2 * dividend + divisor, 2 * divisor);
    }
}
-- People on the sheet. alpha, beta and gamma are optional whole numbers (NULL = left blank).
CREATE TABLE person (
    id    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name  VARCHAR(255) NOT NULL DEFAULT '',
    alpha INTEGER,
    beta  INTEGER,
    gamma INTEGER,
    hold  BOOLEAN NOT NULL DEFAULT FALSE
);

-- A person's patrons: other people on the sheet.
CREATE TABLE person_patron (
    person_id BIGINT NOT NULL REFERENCES person (id) ON DELETE CASCADE,
    patron_id BIGINT NOT NULL REFERENCES person (id) ON DELETE CASCADE,
    PRIMARY KEY (person_id, patron_id)
);
